    const tf = f.fields.find(x => x.type === 'time'); if (!tf) return;
    const tv = arr(tf.values);
    f.fields.filter(x => x.type === 'number').forEach(x => {
      const lb = x.labels || {}, vv = arr(x.values);
      let last = null, lastT = 0;
      for (let i = vv.length - 1; i >= 0; i--) if (vv[i] !== null && vv[i] !== undefined) { last = vv[i]; lastT = tv[i]; break; }
      const name = lb.item || (x.config && x.config.displayNameFromDS) || x.name;
      out.push({host: lb.host || '', item: name, key: lb.item_key || '', t: tv, v: vv, last: last, lastT: lastT,
                pts: tv.map((t, i) => [t, vv[i]]).filter(p => p[1] !== null && p[1] !== undefined)});
    });
  });
  return out;
};
const find = (list, re) => list.find(s => re.test(s.item));
const lastOf = (list, re) => { const s = find(list, re); return s ? s.last : null; };
const problems = ref => {
  const out = [];
