  return out.map(p => ({id: p.eventid || p.triggerid, sev: +p.severity || 0, name: p.name || p.description || '',
    host: (p.hosts && p.hosts[0] && (p.hosts[0].name || p.hosts[0].host)) || '', ts: +p.timestamp || +p.lastchange || 0,
    ack: p.acknowledged === '1' || p.acknowledged === 1}))
    .filter(p => { if (seen[p.id]) return false; seen[p.id] = 1; return true; })
    .sort((a, b) => b.sev - a.sev || b.ts - a.ts);
};
